def is_private_ipv4(text):
    try:
        addr = ipaddress.IPv4Address(text)
    except Exception:
        return False
    if addr.is_loopback or addr.is_link_local or addr.is_multicast or addr.is_reserved or addr.is_unspecified or addr.is_global:
        return False
    if addr in ipaddress.IPv4Network('10.0.0.0/8'):
        return True
    if addr in ipaddress.IPv4Network('172.16.0.0/12'):
        return True
    if addr in ipaddress.IPv4Network('192.168.0.0/16'):
        return True
    return False
